// CLEAN + SEMANTIC CHUNKING
const input = $json.markdown || '';
let text = input
  .replace(/Página\s*\d+/gi, '')
  .replace(/^\s*\d+\s*$/gm, '')
  .replace(/[-=_]{3,}/g, '\n')
  .replace(/&nbsp;/g, ' ')
  .replace(/[●■♦▪✓•–—]/g, '-')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{2,}/g, '\n\n')
  .trim();

let sections = text.split(/(?=^m[oó]dulo|^caso(s)? de [ée]xito|^roadmap|^soporte|^¿quiénes somos\?|^ecosistema mobilvendor|^nuestros beneficios|^censos m[oó]viles|^m[oó]dulo ecommerce)/gmi);
if (sections.length <= 1) sections = [text];

const MAX_CHUNK = 1100;
const OVERLAP = 150;
const out = [];

sections.forEach((section, sectionIndex) => {
  const s = (section || '').trim();
  if (!s) return;

  const title = (s.split('\n')[0] || `Seccion ${sectionIndex+1}`).slice(0, 120);

  if (s.length <= MAX_CHUNK) {
    out.push({ json: { sectionText: `# ${title}\n\n${s}`, sectionIndex, chunkIndex: 0 } });
    return;
  }

  let start = 0;
  let chunkIndex = 0;
  while (start < s.length) {
    const end = Math.min(start + MAX_CHUNK, s.length);
    const chunk = s.slice(start, end).trim();
    if (chunk) {
      out.push({ json: { sectionText: `# ${title}\n\n${chunk}`, sectionIndex, chunkIndex } });
    }
    start += (MAX_CHUNK - OVERLAP);
    chunkIndex++;
  }
});

return out;

const file = $('Set File Metadata').item.json;
const now = new Date().toISOString();

return $input.all().map((item) => {
  const sectionText = item.json.sectionText || '';
  const sectionIndex = item.json.sectionIndex ?? 0;
  const chunkIndex = item.json.chunkIndex ?? 0;

  const metadata = {
    kb: 'brochure',
    folder_id: file.folder_id,
    file_id: file.file_id,
    file_name: file.file_name,
    modified_time: file.modified_time,
    created_time: file.created_time,
    sectionIndex,
    chunkIndex,
    language: 'es',
    content_source: 'google_drive_brochure',
    last_indexed_at: now
  };

  // ID determinístico por chunk (opcional, pero útil)
  const chunk_id = `${file.file_id}:${sectionIndex}:${chunkIndex}`;

  return {
    json: {
      text: sectionText,
      metadata,
      chunk_id
    }
  };
});

const file = $('Set File Metadata').item.json;
const chunks = $input.all();
const now = new Date().toISOString();

let totalChars = 0;
for (const c of chunks) totalChars += (c.json.text || '').length;

return [{
  json: {
    folder_id: file.folder_id,
    file_id: file.file_id,
    file_name: file.file_name,
    modified_time: file.modified_time,
    status: 'ACTIVE',
    chunk_count: chunks.length,
    total_chars: totalChars,
    last_seen_at: now,
    last_indexed_at: now,
    last_error: ''
  }
}];

const driveItems = $('Google Drive - List Folder Files').all();
const alive = new Set(driveItems.map(i => i.json.id).filter(Boolean));

const sheetItems = $('Google Sheets - Read Catalog').all();
const now = new Date().toISOString();

const missing = [];
for (const r of sheetItems) {
  const fileId = r.json.file_id;
  const status = String(r.json.status || '').toUpperCase();
  const folderId = String(r.json.folder_id || '');

  if (!fileId) continue;
  if (folderId && folderId !== '1TW1dAn5k6Qfv5j618EKlf3FStaklHN8V') continue;
  if (status !== 'ACTIVE') continue;

  if (!alive.has(fileId)) {
    missing.push({
      json: {
        file_id: fileId,
        file_name: r.json.file_name || '',
        folder_id: r.json.folder_id || '1TW1dAn5k6Qfv5j618EKlf3FStaklHN8V',
        status: 'DELETED',
        deleted_at: now,
        last_indexed_at: now,
        last_error: ''
      }
    });
  }
}

return missing;

const resource = $('IF PDF Candidate').item.json;
const text = ($json.text || $json.extractedText || '').trim();
const alpha = (text.match(/[A-Za-zÁÉÍÓÚáéíóúÑñ]/g) || []).length;
const density = text.length ? alpha / text.length : 0;
const use_llama = text.length < 900 || density < 0.45;

return [{
  json: {
    ...resource,
    extracted_text: text,
    text_chars: text.length,
    text_density: density,
    use_llama,
    parser_selected: use_llama ? 'llama' : 'n8n_extract'
  },
  binary: $binary
}];

const base = $('Assess Text Quality').item.json;
const markdown = $json.body || $json.data || $json.markdown || '';
return [{ json: { ...base, normalized_text: markdown } }];

const now = new Date().toISOString();
return [{
  json: {
    namespace: 'kbmvlearning',
    filter: { doc_id: { $eq: $json.doc_id } },
    doc_id: $json.doc_id,
    name: $json.name,
    area_id: $json.area_id,
    modulo_id: $json.modulo_id,
    topic_id: $json.topic_id,
    path: $json.path,
    web_url: $json.web_url,
    ext: $json.ext,
    modified_at: $json.modified_at,
    parser_selected: $json.parser_selected,
    last_indexed_at: now
  }
}];

const m = $('Build Delete Filter').item.json;
const chunks = $items('Chunk Text', 0);

return chunks.map((c) => ({
  json: {
    id: `${m.doc_id}:${c.json.chunk_index}`,
    pageContent: c.json.chunk_text,     // <-- CLAVE
    metadata: {
      kb: 'kbmvlearning',
      source: 'sharepoint',
      doc_id: m.doc_id,
      file_name: m.name,
      ext: m.type || m.ext,
      area_id: m.area_id,
      modulo_id: m.modulo_id,
      topic_id: m.topic_id,
      path: m.path,
      web_url: m.web_url,
      modified_at: m.modified_at,
      parser_selected: m.parser_selected,
      chunk_index: c.json.chunk_index,
      language: 'es',
      last_indexed_at: m.last_indexed_at
    }
  }
}));

const base = $('Build Delete Filter').item.json;

// Usar el id del chunk actual para conteo correcto
const currentChunk = $input.item.json;

return [{
  json: {
    doc_id:            base.doc_id,
    processing_status: 'ACTIVE',
    parser_selected:   base.parser_selected,
    chunk_count:       (base.doc_id ? 1 : 0),   // se acumula en Sheets
    total_chars:       (currentChunk.pageContent || '').length,
    last_indexed_at:   base.last_indexed_at,
    last_error:        ''
  }
}];

const input = ($json.normalized_text || '').replace(/\r/g, '');
const clean = input
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

if (!clean) return [];

const MAX_CHUNK = 1200;
const OVERLAP = 180;
const out = [];
let i = 0;
let start = 0;

while (start < clean.length) {
  const end = Math.min(start + MAX_CHUNK, clean.length);
  const chunk = clean.slice(start, end).trim();
  if (chunk) out.push({ json: { ...$json, chunk_text: chunk, chunk_index: i } });
  start += (MAX_CHUNK - OVERLAP);
  i += 1;
}

return out;

const items = $input.all();

const grouped = {};

for (const item of items) {
  const area = item.json.area_id;
  if (!grouped[area]) {
    grouped[area] = [];
  }
  grouped[area].push({
    employee_id: item.json.employee_id,
    email: item.json.email,
    completed_at: item.json.completed_at,
    role: item.json.role
  });
}

return Object.entries(grouped).map(([area_id, employees]) => ({
  json: { area_id, employees }
}));

